{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Ketoprofen, a weakly acidic aromatic ketone with an ionizable carboxyl group, has an estimated absolute oral bioavailability of at least 92% in humans, supporting high F for the similarly acidic and moderately lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "R-ketoprofen showed 84.5% absolute oral bioavailability after a 50 mg oral tablet in healthy subjects, directly demonstrating high oral absorption for a close acidic analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Diflunisal, an acidic salicylic acid derivative, had 89.5% absolute oral bioavailability, supporting high F for the query's weakly acidic enol and lipophilic aromatic system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Cromolyn has less than 1% oral systemic availability, but its highly polar, multiply ionized dicarboxylic acid structure is not transferable to the more lipophilic, less polar query; this contradictory evidence carries low weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a 4-hydroxycoumarin weak acid. Multiple acidic, moderately lipophilic analogues (ketoprofen, R-ketoprofen, diflunisal) show absolute oral bioavailability of 84–92%, strongly supporting F ≥ 20%. The low-bioavailability counterexamples are far more polar or poorly permeable and do not transfer to this scaffold. Physicochemical ionization concerns are outweighed by consistent experimental evidence of high oral bioavailability in close analogues.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for the exact query molecule is present in the supplied evidence.",
    "All supplied analogues have low Morgan similarity (~0.25–0.29), so transferability relies on shared physicochemical and structural features rather than high structural identity.",
    "No direct first-pass metabolism or clearance data for the query are provided, though the high-F analogues indicate that acidic ionization does not preclude excellent oral absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

